package com.mfix.pos;

import android.os.Bundle;
import android.view.View;
import android.view.ViewGroup;
import android.webkit.WebView;

/** Adds controlled stock adjustment and low-stock visibility on top of the active POS launcher. */
public class StockControlPatchActivity extends RoleGuardPatchActivity {
    private static final String PATCH =
        "(function(){if(window.__mfixStockControlV1)return;window.__mfixStockControlV1=true;"+
        "function esc(s){return String(s==null?'':s).replace(/[&<>\\\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\\\"':'&quot;',\"'\":'&#39;'}[c];});}"+
        "function save(){try{saveKey('products',STATE.products);saveKey('misc',{returns:STATE.returns,shifts:STATE.shifts,giftCards:STATE.giftCards,preorders:STATE.preorders,auditLog:STATE.auditLog,inventoryHistory:STATE.inventoryHistory});}catch(e){console.error(e);}}"+
        "function render(){var v=document.getElementById('view-inventory');if(!v)return false;if(document.getElementById('mfixStockControl'))return true;var b=document.createElement('div');b.id='mfixStockControl';b.className='card';b.style.marginBottom='12px';var ps=Array.isArray(STATE.products)?STATE.products:[];var low=ps.filter(function(p){return Number(p.stock||0)<=Number(p.minStock==null?2:p.minStock);}).slice(0,12);b.innerHTML='<div class=\\\"section-title\\\">📦 בקרת מלאי</div><div class=\\\"muted\\\">התאמת מלאי ידנית עם סיבה ותיעוד בהיסטוריה.</div><div style=\\\"display:flex;gap:8px;flex-wrap:wrap;margin-top:10px\\\"><select id=\\\"mfixStockProduct\\\" class=\\\"input\\\" style=\\\"max-width:320px\\\"><option value=\\\"\\\">בחר מוצר</option>'+ps.map(function(p){return '<option value=\\\"'+esc(p.id)+'\\\">'+esc(p.name||p.sku||p.id)+' · מלאי '+Number(p.stock||0)+'</option>';}).join('')+'</select><input id=\\\"mfixStockQty\\\" class=\\\"input\\\" type=\\\"number\\\" style=\\\"max-width:130px\\\" placeholder=\\\"כמות\\\"><select id=\\\"mfixStockReason\\\" class=\\\"input\\\" style=\\\"max-width:220px\\\"><option>קבלת סחורה</option><option>ספירת מלאי</option><option>נזק</option><option>אובדן</option><option>תיקון ידני</option></select><button id=\\\"mfixStockAdd\\\" class=\\\"btn btn-primary\\\">+ הוסף</button><button id=\\\"mfixStockRemove\\\" class=\\\"btn btn-outline\\\">− הורד</button></div><div style=\\\"margin-top:12px\\\"><b>מלאי נמוך</b><div id=\\\"mfixLowRows\\\"></div></div>';v.insertBefore(b,v.firstChild);function lowDraw(){var a=ps.filter(function(p){return Number(p.stock||0)<=Number(p.minStock==null?2:p.minStock);}).slice(0,12);b.querySelector('#mfixLowRows').innerHTML=a.length?'<table class=\\\"tbl\\\"><thead><tr><th>מוצר</th><th>מלאי</th><th>סף</th></tr></thead><tbody>'+a.map(function(p){return '<tr><td>'+esc(p.name||p.sku||p.id)+'</td><td>'+Number(p.stock||0)+'</td><td>'+Number(p.minStock==null?2:p.minStock)+'</td></tr>';}).join('')+'</tbody></table>':'<div class=\\\"empty-state\\\">אין מוצרים מתחת לסף</div>';}function adjust(delta){var id=b.querySelector('#mfixStockProduct').value,q=Math.floor(Number(b.querySelector('#mfixStockQty').value||0)),reason=b.querySelector('#mfixStockReason').value,p=ps.find(function(x){return String(x.id)===String(id);});if(!p||q<=0){if(window.toast)window.toast('בחר מוצר והזן כמות חיובית','warn');return;}var before=Number(p.stock||0),after=Math.max(0,before+delta*q);if(delta<0&&q>before){if(window.toast)window.toast('אין מספיק מלאי להורדה','err');return;}p.stock=after;if(!Array.isArray(STATE.inventoryHistory))STATE.inventoryHistory=[];STATE.inventoryHistory.unshift({id:'invh_'+Date.now(),productId:p.id,type:delta>0?'adjust_in':'adjust_out',qty:q,before:before,after:after,reason:reason,at:new Date().toISOString()});save();b.querySelector('#mfixStockQty').value='';var opt=b.querySelector('#mfixStockProduct option[value=\\\"'+esc(p.id)+'\\\"]');if(opt)opt.textContent=(p.name||p.sku||p.id)+' · מלאי '+after;lowDraw();if(window.toast)window.toast('המלאי עודכן','ok');}b.querySelector('#mfixStockAdd').onclick=function(){adjust(1);};b.querySelector('#mfixStockRemove').onclick=function(){adjust(-1);};lowDraw();return true;}var n=0,t=setInterval(function(){if(render()||n++>=40)clearInterval(t);},500);})();";
    @Override protected void onCreate(Bundle savedInstanceState){
        super.onCreate(savedInstanceState);
        View root=((ViewGroup)findViewById(android.R.id.content)).getChildAt(0);
        if(root instanceof WebView)((WebView)root).postDelayed(()->((WebView)root).evaluateJavascript(PATCH,null),10500);
    }
}
